"""Renders `docs/TRACEABILITY.md` from the registry, test results and data manifests."""

from collections import Counter, defaultdict
from collections.abc import Iterable

from oran_causal.trace.manifests import Manifests
from oran_causal.trace.registry import CLAIM_KINDS, Claim, Evidence, Registry
from oran_causal.trace.results import MarkedTest

HEADER = (
    "# Traceability matrix\n\n"
    "Generated by `oran-causal-trace matrix` from `spec/claims.yaml`, `build/trace/tests.json` "
    "and `data/manifests/`. Do not edit by hand.\n"
)


def _cell(text: str) -> str:
    return text.replace("|", "\\|").replace("\n", " ")


def _codes(items: Iterable[str]) -> str:
    return ", ".join(f"`{item}`" for item in items) or "-"


def _manifest_state(evidence: Evidence, manifests: Manifests | None) -> str:
    if manifests is None or evidence.record_set not in manifests:
        return "no manifest"
    listed = manifests[evidence.record_set].get(evidence.record_path)
    if listed is None:
        return "not in manifest"
    return "ok" if listed == evidence.sha256.lower() else "sha mismatch"


def _evidence_cell(claim: Claim, manifests: Manifests | None) -> str:
    cells = [
        f"`{e.record}`@{e.sha256[:8]} ({_manifest_state(e, manifests)})" for e in claim.evidence
    ]
    return "<br>".join(cells) or "-"


def _tests_cell(claim: Claim, passed: Counter[str] | None) -> str:
    count = "n/a" if passed is None else str(passed[claim.id])
    return f"{count}/{claim.tests_min}"


def _summary(claims: tuple[Claim, ...], passed: Counter[str] | None) -> list[str]:
    lines = ["| Kind | Claims | Tests met | With evidence |", "|---|---|---|---|"]
    for kind in CLAIM_KINDS:
        group = [claim for claim in claims if claim.kind == kind]
        met = "n/a" if passed is None else str(sum(passed[c.id] >= c.tests_min for c in group))
        with_evidence = sum(bool(claim.evidence) for claim in group)
        lines.append(f"| {kind} | {len(group)} | {met} | {with_evidence} |")
    return lines


def _claim_rows(
    claims: tuple[Claim, ...], passed: Counter[str] | None, manifests: Manifests | None
) -> list[str]:
    lines = [
        "| ID | Kind | Statement | Paper | Spec | Depends on | Code | Tests | Evidence |",
        "|---|---|---|---|---|---|---|---|---|",
    ]
    for claim in claims:
        status = "" if claim.active else " (retracted)"
        cells = [
            f"{claim.id}{status}",
            claim.kind,
            _cell(claim.statement),
            _codes(claim.paper),
            f"`{claim.spec}`",
            ", ".join(claim.depends_on + claim.probes) or "-",
            _codes(claim.code),
            _tests_cell(claim, passed),
            _evidence_cell(claim, manifests),
        ]
        lines.append(f"| {' | '.join(cells)} |")
    return lines


def _test_index(tests: tuple[MarkedTest, ...] | None) -> list[str]:
    if tests is None:
        return ["No test results: `build/trace/tests.json` not found."]
    lines = ["| Test | Claims | Outcome |", "|---|---|---|"]
    lines += [f"| `{t.nodeid}` | {', '.join(t.claims) or '-'} | {t.outcome} |" for t in tests]
    return lines


def _record_index(claims: tuple[Claim, ...]) -> list[str]:
    users: dict[str, list[str]] = defaultdict(list)
    for claim in claims:
        for evidence in claim.evidence:
            users[evidence.record].append(claim.id)
    lines = ["| Record | Claims |", "|---|---|"]
    lines += [
        f"| `{record}` | {', '.join(sorted(set(ids)))} |" for record, ids in sorted(users.items())
    ]
    return lines


def render(
    registry: Registry, tests: tuple[MarkedTest, ...] | None, manifests: Manifests | None
) -> str:
    """Render the matrix as Markdown.

    Args:
        registry: The loaded claims registry.
        tests: Claim-marked test results, or `None` when no run was recorded.
        manifests: Data manifests, or `None` when `data/manifests` is absent.

    Returns:
        The document text with LF line endings and no run-dependent timestamps.
    """
    passed = None
    if tests is not None:
        passed = Counter(c for test in tests if test.passed for c in set(test.claims))
    sections = [
        [HEADER, "## Summary", "", *_summary(registry.claims, passed)],
        ["", "## Claims", "", *_claim_rows(registry.claims, passed, manifests)],
        ["", "## Tests", "", *_test_index(tests)],
        ["", "## Records", "", *_record_index(registry.claims)],
    ]
    return "\n".join(line for section in sections for line in section) + "\n"
